/** Looks up tool rental rates by serial number.
 * Falls back to { operRate: 0, standbyRate: 0 } if serial not found.
 */
export function getToolRate(serial: string): { operRate: number; standbyRate: number } {
  return TOOL_RATES[serial] ?? { operRate: 0, standbyRate: 0 };
}
